    </main>

    <script>
    // 1. Cargamos los datos de la BD
    const datosZonas = <?php echo $datos_json; ?>;
    console.log("Base de datos cargada:", datosZonas);

    // 2. SELECCIÓN AUTOMÁTICA: Agarramos todos los paths del SVG sin importar la clase
    const municipios = document.querySelectorAll('.col-mapa-svg svg path');
    console.log("Se encontraron " + municipios.length + " municipios en el mapa.");

    // 3. Asignamos el clic a cada pedacito del mapa
    municipios.forEach(municipio => {
        municipio.addEventListener('click', function() {
            
            // Obtenemos el ID del municipio que tocaste
            const slugSeleccionado = this.id; 
            
            // Si tocaste un municipio al que aún no le has puesto ID en tu HTML
            if (!slugSeleccionado) {
                alert("⚠️ A este pedazo del mapa le falta el id='...' en tu código HTML.");
                return; // Detenemos la función aquí
            }

            console.log("Clickeaste el municipio con ID:", slugSeleccionado);

            // Buscamos ese ID en tus datos de la base de datos
            const info = datosZonas.find(z => z.slug === slugSeleccionado);

            if(info) {
                console.log("¡Éxito! Datos encontrados:", info);
                
                // Mostrar panel y ocultar instrucciones
                document.getElementById('instruccion-guia').style.display = 'none';
                document.getElementById('visual-datos').style.display = 'block';
                
                // Llenar textos
                document.getElementById('d-titulo').innerText = info.nombre_area;
                document.getElementById('txt-bosque').innerText = info.cobertura_forestal + '%';
                document.getElementById('txt-amenaza').innerText = info.riesgo_amenaza + '%';
                document.getElementById('txt-especie').innerText = info.especie_bandera;
                document.getElementById('txt-densidad').innerText = info.densidad_fauna;

                // Restablecer anchos a 0 primero para que la animación se vea fluida
                document.getElementById('bar-bosque').style.width = '0%';
                document.getElementById('bar-amenaza').style.width = '0%';

                // Animación barras
                setTimeout(() => {
                    document.getElementById('bar-bosque').style.width = info.cobertura_forestal + '%';
                    document.getElementById('bar-amenaza').style.width = info.riesgo_amenaza + '%';
                }, 50);

                // Colorear el municipio seleccionado en el mapa
                municipios.forEach(p => p.classList.remove('zona-activa'));
                this.classList.add('zona-activa');

            } else {
                // Si el ID de tu HTML no existe en tu tabla de DBeaver
                alert("❌ ERROR: El ID '" + slugSeleccionado + "' no existe en tu base de datos. Revisa cómo lo escribiste.");
            }
        });
    });
</script>
